function minimalComponentTokens() {
  const c = (name, light, dark) => makeModeToken(name, light, dark, componentScopes(name));
  return [
    c("Component colors/Components/Icons/icon-fg-primary", "{Colors.Foreground.fg-primary}", "{Colors.Foreground.fg-primary}"),
    c("Component colors/Components/Icons/icon-fg-secondary", "{Colors.Foreground.fg-secondary}", "{Colors.Foreground.fg-secondary}"),
    c("Component colors/Components/Icons/icon-fg-brand", "{Colors.Foreground.fg-brand-primary}", "{Colors.Foreground.fg-brand-primary}"),
    c("Component colors/Components/Featured icons/featured-icon-bg-brand", "{Colors.Background.bg-brand-primary}", "{Colors.Background.bg-brand-primary}"),
    c("Component colors/Components/Featured icons/featured-icon-fg-brand", "{Colors.Base.white}", "{Colors.Base.white}"),
    c("Component colors/Components/Avatars/avatar-bg", "{Colors.Background.bg-secondary}", "{Colors.Background.bg-secondary}"),
    c("Component colors/Components/Avatars/avatar-border", "{Colors.Border.border-primary}", "{Colors.Border.border-primary}"),
    c("Component colors/Components/Social/social-icon-fg-x", "#242e36", "#f2f4f7"),
    c("Component colors/Components/Social/social-icon-fg-github", "#24292f", "#f2f4f7"),
    c("Component colors/Components/Social/social-icon-fg-linkedin", "#0a66c2", "#0a66c2"),
  ];
}

function makeStarterPreset(id, label, description, palette) {
  const primitives = [
    ...basePrimitives({ white: palette.white, black: palette.black, transparent: "rgba(255, 255, 255, 0)" }),
    ...primitivesFromScale("Gray (light mode)", palette.grayLight),
    ...primitivesFromScale("Gray (dark mode)", palette.grayDark),
    ...primitivesFromScale("Brand", palette.brand),
    ...primitivesFromScale("Error", palette.error),
    ...primitivesFromScale("Warning", palette.warning),
    ...primitivesFromScale("Success", palette.success),
  ];

  return {
    id,
    label,
    description,
    primitives,
    semanticTokens: minimalSemanticTokens(),
    componentTokens: minimalComponentTokens(),
    brandShades: [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950],
  };
}

