function getPresetById(presetId) {
  return BUILTIN_PRESETS.find((preset) => preset.id === presetId);
}

const UI_WIDTH = 620;
const UI_HEIGHT = 760;
figma.showUI(__html__, { width: UI_WIDTH, height: UI_HEIGHT, themeColors: true });

function normalizeLookup(value) {
  return String(value).toLowerCase().replace(/[{}\s()_\-./]/g, "");
}

function aliasCandidates(reference) {
  const raw = String(reference).trim().replace(/^\{/, "").replace(/\}$/, "").trim();
  return [raw, raw.replace(/\./g, "/"), raw.replace(/\//g, ".")];
}

function isAliasString(value) {
  return typeof value === "string" && /^\{[^{}]+\}$/.test(value.trim());
}

function addAliasEntry(index, variable) {
  const normalizedNames = [variable.name, variable.name.replace(/\//g, ".")]
    .map((candidate) => normalizeLookup(candidate))
    .filter(Boolean);

  if (!index.byCollection.has(variable.variableCollectionId)) {
    index.byCollection.set(variable.variableCollectionId, new Map());
  }

  const byCollection = index.byCollection.get(variable.variableCollectionId);
  for (const normalized of normalizedNames) {
    if (!index.global.has(normalized)) index.global.set(normalized, variable);
    if (!byCollection.has(normalized)) byCollection.set(normalized, variable);
  }
}

function resolveAlias(index, aliasRef, collectionId) {
  const withinCollection = index.byCollection.get(collectionId);
  for (const candidate of aliasCandidates(aliasRef)) {
    const normalized = normalizeLookup(candidate);
    if (!normalized) continue;
    if (withinCollection && withinCollection.has(normalized)) return withinCollection.get(normalized);
    if (index.global.has(normalized)) return index.global.get(normalized);
  }
  return null;
}

function makeAlias(variable) {
  if (figma.variables.createVariableAlias) {
    return figma.variables.createVariableAlias(variable);
  }
  return { type: "VARIABLE_ALIAS", id: variable.id };
}

function toRgba(value) {
  return parseColorInput(value);
}

function getOrCreateCollection(name, collectionIndex) {
  const existing = collectionIndex.get(name);
  if (existing) return existing;
  const created = figma.variables.createVariableCollection(name);
  collectionIndex.set(name, created);
  return created;
}

function ensureModes(collection, desiredModes) {
  const modeByName = {};
  for (const mode of collection.modes) modeByName[mode.name] = mode.modeId;

  const deduped = Array.from(new Set((desiredModes || []).map((m) => String(m).trim()).filter(Boolean)));
  if (!deduped.length) return modeByName;

  if (collection.modes.length === 1 && deduped.length === 1 && !modeByName[deduped[0]] && collection.renameMode) {
    collection.renameMode(collection.modes[0].modeId, deduped[0]);
    return ensureModes(collection, deduped);
  }

  for (const modeName of deduped) {
    if (!modeByName[modeName]) {
      modeByName[modeName] = collection.addMode(modeName);
    }
  }

  return modeByName;
}

function upsertColorVariable(collection, variableName, variableIndex, report) {
  const key = collection.id + "::" + variableName;
  const existing = variableIndex.get(key);

  if (existing) {
    if (existing.resolvedType !== "COLOR") {
      report.conflicts.push("Type conflict on '" + collection.name + "/" + variableName + "': existing=" + existing.resolvedType + ", new=COLOR");
      return null;
    }
    report.updated += 1;
    const cr = report.collections.find((item) => item.name === collection.name);
    if (cr) cr.updated += 1;
    return existing;
  }

  const created = figma.variables.createVariable(variableName, collection.id, "COLOR");
  variableIndex.set(key, created);
  report.created += 1;
  const cr = report.collections.find((item) => item.name === collection.name);
  if (cr) cr.created += 1;
  return created;
}

function buildGenerationOptions(raw) {
  if (!raw || typeof raw !== "object") {
    throw new Error("Payload generation invalide.");
  }

  const input = raw;
  const brandsInput = Array.isArray(input.brands) ? input.brands : [];

  const brands = brandsInput
    .slice(0, 10)
    .filter((entry) => entry && typeof entry === "object")
    .map((entry) => ({ name: String(entry.name || "").trim(), color: String(entry.color || "").trim() }))
    .filter((entry) => entry.color.length > 0);

  for (const brand of brands) {
    parseColorInput(brand.color);
  }

  return {
    presetId: String(input.presetId || ""),
    generateDark: input.generateDark !== false,
    includeComponents: input.includeComponents !== false,
    brands,
  };
}

function mergePrimitives(base, customBrands) {
  const merged = new Map();
  for (const primitive of base) merged.set(primitive.name, primitive.value);
  for (const primitive of customBrands) merged.set(primitive.name, primitive.value);
  return Array.from(merged.entries()).map(([name, value]) => ({ name, value }));
}

function selectModeTokens(preset, includeComponents) {
  return includeComponents ? preset.semanticTokens.concat(preset.componentTokens) : preset.semanticTokens.slice();
}

function postPresetList() {
  figma.ui.postMessage({
    type: "preset-list",
    presets: BUILTIN_PRESETS.map((preset) => ({
      id: preset.id,
      label: preset.label,
      description: preset.description,
      primitiveCount: preset.primitives.length,
      semanticCount: preset.semanticTokens.length,
      componentCount: preset.componentTokens.length,
      brandShades: preset.brandShades,
    })),
  });
}

function applyPresetGeneration(options) {
  const preset = getPresetById(options.presetId);
  if (!preset) throw new Error("Preset inconnu: " + options.presetId);

  const darkEnabled = !!options.generateDark;
  const brandPrimitives = buildBrandPrimitives(options.brands, preset.brandShades);
  const primitives = mergePrimitives(preset.primitives, brandPrimitives);
  const modeTokens = selectModeTokens(preset, options.includeComponents);

  const report = {
    created: 0,
    updated: 0,
    aliasApplied: 0,
    aliasMissing: 0,
    conflicts: [],
    collections: [
      { name: "_Primitives", created: 0, updated: 0 },
      { name: "1. Color modes", created: 0, updated: 0 },
    ],
  };

  const collectionIndex = new Map(figma.variables.getLocalVariableCollections().map((c) => [c.name, c]));
  const localVariables = figma.variables.getLocalVariables();
  const variableIndex = new Map(localVariables.map((v) => [v.variableCollectionId + "::" + v.name, v]));

  const aliasIndex = { global: new Map(), byCollection: new Map() };
  for (const variable of localVariables) addAliasEntry(aliasIndex, variable);

  const primitivesCollection = getOrCreateCollection("_Primitives", collectionIndex);
  const primitivesModes = ensureModes(primitivesCollection, ["Style"]);
  const primitivesModeId = primitivesModes.Style || primitivesCollection.modes[0].modeId;

  const colorModesCollection = getOrCreateCollection("1. Color modes", collectionIndex);
  const desiredModes = darkEnabled ? ["Light mode", "Dark mode"] : ["Light mode"];
  const colorModeIds = ensureModes(colorModesCollection, desiredModes);

  const pendingAliases = [];

  for (const primitive of primitives) {
    const variable = upsertColorVariable(primitivesCollection, primitive.name, variableIndex, report);
    if (!variable) continue;

    if (isAliasString(primitive.value)) {
      pendingAliases.push({ variable, modeId: primitivesModeId, aliasRef: primitive.value, collectionId: primitivesCollection.id });
    } else {
      variable.setValueForMode(primitivesModeId, toRgba(primitive.value));
    }

    addAliasEntry(aliasIndex, variable);
  }

  for (const token of modeTokens) {
    const variable = upsertColorVariable(colorModesCollection, token.name, variableIndex, report);
    if (!variable) continue;

    variable.scopes = sanitizeScopes(token.scopes);

    const lightModeId = colorModeIds["Light mode"] || colorModesCollection.modes[0].modeId;
    if (isAliasString(token.light)) {
      pendingAliases.push({ variable, modeId: lightModeId, aliasRef: token.light, collectionId: colorModesCollection.id });
    } else {
      variable.setValueForMode(lightModeId, toRgba(token.light));
    }

    if (darkEnabled) {
      const darkModeId = colorModeIds["Dark mode"];
      if (darkModeId) {
        if (isAliasString(token.dark)) {
          pendingAliases.push({ variable, modeId: darkModeId, aliasRef: token.dark, collectionId: colorModesCollection.id });
        } else {
          variable.setValueForMode(darkModeId, toRgba(token.dark));
        }
      }
    }

    addAliasEntry(aliasIndex, variable);
  }

  for (const alias of pendingAliases) {
    const target = resolveAlias(aliasIndex, alias.aliasRef, alias.collectionId);
    if (!target) {
      report.aliasMissing += 1;
      report.conflicts.push("Alias unresolved: " + alias.variable.name + " -> " + alias.aliasRef);
      continue;
    }

    alias.variable.setValueForMode(alias.modeId, makeAlias(target));
    report.aliasApplied += 1;
  }

  return report;
}

figma.ui.onmessage = (msg) => {
  try {
    if (msg && msg.type === "ui-ready") {
      postPresetList();
      return;
    }

    if (msg && msg.type === "generate-variables") {
      const options = buildGenerationOptions(msg.payload);
      const report = applyPresetGeneration(options);

      figma.notify(
        "Starter tokens generes: +" + report.created + " / ~" + report.updated + " / aliases " + report.aliasApplied +
          (report.aliasMissing ? " / manquants " + report.aliasMissing : "")
      );

      figma.ui.postMessage({ type: "generate-result", report });
    }
  } catch (error) {
    const message = error && error.message ? error.message : String(error);
    figma.notify("Erreur: " + message, { error: true });
    figma.ui.postMessage({ type: "generate-error", message });
  }
};
